class Solution {
public:
    int rob(vector<int>& nums) {
        int rob1 = 0, rob2 = 0;
        for (int n : nums) {
            int new_rob = max(rob2, rob1 + n);
            rob1 = rob2;
            rob2 = new_rob;
        }
        return rob2;
    }
};

class Solution {
    public int rob(int[] nums) {
        int rob1 = 0, rob2 = 0;
        for (int n : nums) {
            int newRob = Math.max(rob2, rob1 + n);
            rob1 = rob2;
            rob2 = newRob;
        }
        return rob2;
    }
}

/**
 * @param {number[]} nums
 * @return {number}
 */
var rob = function(nums) {
    let rob1 = 0, rob2 = 0;
    for (const n of nums) {
        const newRob = Math.max(rob2, rob1 + n);
        rob1 = rob2;
        rob2 = newRob;
    }
    return rob2;
};
